public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {

// Create a new mapping object
IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>();

// Add a mapping from each vertex to itself
for (V vertex : graph.getVertices()) {
    mapping.addMapping(vertex, vertex);
}

// Add a mapping from each edge to itself
for (E edge : graph.getEdges()) {
    mapping.addMapping(edge, edge);
}

// Return the mapping
