private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label 0 to the bucket with label minLabel
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).size() > 0 && labels.get(i) < minLabel) {
            bucketsByLabel.get(minLabel).addAll(bucketsByLabel.get(i));
            bucketsByLabel.get(i).clear();
            labels.set(i, minLabel);
        }
    }

    // Clear the bucket with label 0
    bucketsByLabel.get(0).clear();
}

