public static int countOccurrencesOf(String str, String sub) {

     // Base case: if either string is null or empty, return 0
     if (str == null || sub == null || str.isEmpty() || sub.isEmpty()) {
          return 0;
     }

     // Initialization: set the count to 0
     int count = 0;

     // Loop through each character in the string
     for (int i = 0; i < str.length(); i++) {
          // If the character at the current position matches the first character of the substring
          if (str.charAt(i) == sub.charAt(0)) {
               // Check if the substring starts at the current position
               if (str.substring(i, i + sub.length()).equals(sub)) {
                    // If it does, increment the count and move the starting index forward
                    count++;
                    i += sub.length() - 1;
               }
          }
     }

     // Return the count
     return count;
}

