    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (var reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                ThreadSnapshot snapshot = ThreadSnapshot.parseFromString(line);

                // check if the snapshot falls within the time range
                for (var timeRange : timeRanges) {
                    if (timeRange.getStartTime() <= snapshot.getTime() && timeRange.getEndTime() >= snapshot.getTime()) {
                        snapshots.add(snapshot);
                        break;
